"""Note model for notekeeper."""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from datetime import datetime, timezone


@dataclass
class Note:
    """A single note with optional tags."""

    content: str
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    created_at: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )
    tags: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        """Convert note to a plain dict for JSON serialization."""
        return {
            "id": self.id,
            "content": self.content,
            "created_at": self.created_at,
            "tags": list(self.tags),
        }

    @classmethod
    def from_dict(cls, data: dict) -> Note:
        """Reconstruct a Note from a dict."""
        return cls(
            id=data["id"],
            content=data["content"],
            created_at=data["created_at"],
            tags=list(data.get("tags", [])),
        )

    def add_tag(self, tag: str) -> None:
        """Add a tag to the note (no duplicates)."""
        tag = tag.strip()
        if tag and tag not in self.tags:
            self.tags.append(tag)

    def remove_tag(self, tag: str) -> bool:
        """Remove a tag; returns True if it was present."""
        if tag in self.tags:
            self.tags.remove(tag)
            return True
        return False

"""High-level note operations."""

from __future__ import annotations

from typing import TYPE_CHECKING

from notekeeper.note import Note

if TYPE_CHECKING:
    from notekeeper.storage import Storage


class NoteManager:
    """Coordinates note operations and storage."""

    def __init__(self, storage: Storage) -> None:
        self._storage = storage
        self._notes: list[Note] = []
        self._load()

    # ------------------------------------------------------------------
    # private
    # ------------------------------------------------------------------

    def _load(self) -> None:
        self._notes = self._storage.load()

    def _persist(self) -> None:
        self._storage.save(self._notes)

    # ------------------------------------------------------------------
    # public – queries
    # ------------------------------------------------------------------

    def all_notes(self) -> list[Note]:
        return list(self._notes)

    def get_by_id(self, note_id: str) -> Note | None:
        for note in self._notes:
            if note.id == note_id:
                return note
        return None

    def search(self, term: str, case_sensitive: bool = False) -> list[Note]:
        """Return notes whose content contains *term*."""
        term = term if case_sensitive else term.lower()
        results = []
        for note in self._notes:
            text = note.content if case_sensitive else note.content.lower()
            if term in text:
                results.append(note)
        return results

    def find_by_tag(self, tag: str) -> list[Note]:
        """Return notes that have the given tag."""
        tag = tag.strip()
        return [n for n in self._notes if tag in n.tags]

    # ------------------------------------------------------------------
    # public – mutations
    # ------------------------------------------------------------------

    def add(self, content: str, tags: list[str] | None = None) -> Note:
        note = Note(content=content, tags=list(tags) if tags else [])
        self._notes.insert(0, note)
        self._persist()
        return note

    def delete(self, note_id: str) -> bool:
        """Delete note by id. Returns True if it existed."""
        for i, note in enumerate(self._notes):
            if note.id == note_id:
                self._notes.pop(i)
                self._persist()
                return True
        return False

    def tag_note(self, note_id: str, *tags: str) -> Note | None:
        """Add one or more tags to a note. Returns updated note or None."""
        note = self.get_by_id(note_id)
        if note is None:
            return None
        for t in tags:
            note.add_tag(t)
        self._persist()
        return note

    def untag_note(self, note_id: str, tag: str) -> Note | None:
        """Remove a tag from a note. Returns updated note or None."""
        note = self.get_by_id(note_id)
        if note is None:
            return None
        note.remove_tag(tag)
        self._persist()
        return note

    def update_content(self, note_id: str, content: str) -> Note | None:
        """Replace the content of a note."""
        note = self.get_by_id(note_id)
        if note is None:
            return None
        note.content = content
        self._persist()
        return note

