from __future__ import annotations

import pytest
from notekeeper.manager import NoteManager
from notekeeper.storage import Storage
from notekeeper.note import Note
import tempfile
import os


@pytest.fixture
def tmp_json_path():
    """A temporary JSON file path that is cleaned up after each test."""
    fd, path = tempfile.mkstemp(suffix=".json")
    os.close(fd)
    os.unlink(path)  # remove so Storage starts fresh
    yield path
    if os.path.exists(path):
        os.unlink(path)


@pytest.fixture
def storage(tmp_json_path):
    """A Storage instance backed by a temporary file."""
    return Storage(tmp_json_path)


@pytest.fixture
def manager(storage):
    """A NoteManager with the temporary storage."""
    return NoteManager(storage)


